<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/tax_profile_service.php';
try{$u=requireAuth();$uid=(int)$u->id;$date=trim((string)($_GET['date']??date('Y-m-d')));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new Exception('Invalid effective date');$conn=db();requireAnyPermission($conn,$uid,['products.view','services.view','invoices.view','supplierInvoices.create','reports.view']);ensureTaxProfileSchema($conn);$s=$conn->prepare("SELECT id,name,vat_rate,vat_exempt,fodec_applicable,fodec_rate,tax_regime,deductibility_rate,legal_basis,certificate_reference,effective_from,effective_to FROM erp_tax_profiles WHERE user_id=? AND effective_from<=? AND (effective_to IS NULL OR effective_to>=?) ORDER BY name");$s->bind_param('iss',$uid,$date,$date);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();jsonResponse(['success'=>true,'date'=>$date,'profiles'=>$rows]);}catch(Throwable $e){jsonResponse(['success'=>false,'message'=>$e->getMessage()],400);}
